const navLabels: Record<string, string> = { "/": "Overview", "/projects": "Projects", "/tasks": "Tasks", "/changes": "Code changes", "/audits": "Security audit", "/automation": "Automation", "/testing": "Testing", "/reports": "Reports", "/assistant": "Assistant" };
const statusColors: Record<string, string> = { Pending: "bg-slate-100 text-slate-700", "In Progress": "bg-amber-100 text-amber-800", Done: "bg-emerald-100 text-emerald-800" };
const severityColors: Record<string, string> = { Critical: "bg-red-100 text-red-800", High: "bg-orange-100 text-orange-800", Medium: "bg-amber-100 text-amber-800", Low: "bg-sky-100 text-sky-800" };

function listFromJson(value: string | null) {
  try { return value ? JSON.parse(value) as string[] : []; } catch { return []; }
}

function friendlyBuilderError(message: string) {
  if (/invalid structured proposal|could not produce a valid proposal/i.test(message)) return "AI response proposal format mein complete nahi tha. System ne retry kiya lekin valid structure nahi mila. Dobara try karein; bohot large project ho to pehle MVP ya ek module ka prompt dein.";
  return message;
}

function isSoftwareBuildIntent(prompt: string) {
  const value = prompt.toLowerCase();
  const actionAndArtifact = /\b(build|create|make|develop|code|implement|generate|design|fix|update|add|banao|banayein|bnao|tayyar|tyar|tayar|बनाओ|बनाना|बनाएं|तैयार|कोड)\b/.test(value) && /\b(website|web app|application|app|software|tool|api|script|automation|dashboard|portal|project|system|platform|codebase|site|feature|फाइल|वेबसाइट|ऐप|सॉफ्टवेयर|एप्लिकेशन)\b/.test(value);
  const concreteProductBrief = value.length > 180 && /\b(vertical ai|saas|mvp|workflow|marketing kit|listing|agent|product|platform|tech stack|frontend|backend|pricing)\b/.test(value) && /\b(photos?|address|social|website|video|qr|api|database|users?|generate)\b/.test(value);
  return actionAndArtifact || concreteProductBrief;
}

function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.2em] text-primary">{eyebrow}</p><h1 className="text-3xl font-semibold tracking-[-0.03em] text-slate-950 md:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{description}</p></div>{action}</div>;
}

function Overview() {
  const [, setLocation] = useLocation();
  const { data, isLoading } = trpc.dashboard.summary.useQuery();
  const projects = data?.projects ?? [];
  const tasks = data?.tasks ?? [];
  const active = tasks.filter((task) => task.status !== "Done").length;
  const audits = data?.audits ?? [];
  const testRuns = data?.testRuns ?? [];
  return <>
    <SectionHeading eyebrow="Engineering intelligence" title="Clarity for every codebase." description="Inspect projects, coordinate engineering work, and keep delivery risk visible from one calm command center." action={<Button onClick={() => setLocation("/projects")} className="rounded-full bg-slate-950 px-5 shadow-lg shadow-slate-950/10"><Plus className="mr-2 size-4" /> New project</Button>} />
    <div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      {[{ label: "Connected projects", value: projects.length, icon: FolderKanban, note: "Across your workspace" }, { label: "Active tasks", value: active, icon: Timer, note: "Pending or In Progress" }, { label: "Audits recorded", value: audits.length, icon: ShieldAlert, note: "Rule-based checks" }, { label: "Test runs", value: testRuns.length, icon: TestTube2, note: "Recorded validations" }].map((item) => <Card key={item.label} className="border-0 bg-white/80 shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardContent className="p-5"><div className="mb-6 flex items-center justify-between"><span className="flex size-10 items-center justify-center rounded-2xl bg-slate-100"><item.icon className="size-5 text-slate-700" /></span><ArrowUpRight className="size-4 text-slate-300" /></div><p className="text-3xl font-semibold tracking-tight text-slate-950">{isLoading ? "—" : item.value}</p><p className="mt-1 text-sm font-medium text-slate-700">{item.label}</p><p className="mt-1 text-xs text-slate-400">{item.note}</p></CardContent></Card>)}
    </div>
    <div className="grid gap-6 xl:grid-cols-[1.35fr_0.65fr]">
      <Card className="border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardHeader className="flex flex-row items-center justify-between border-b border-slate-100"><div><CardTitle className="text-base">Project overview</CardTitle><p className="mt-1 text-xs text-slate-400">Your latest connected codebases</p></div><GitBranch className="size-5 text-slate-300" /></CardHeader><CardContent className="p-0">{projects.length === 0 ? <EmptyState icon={FolderKanban} title="No projects yet" body="Connect a project to start an evidence-based engineering workspace." /> : projects.slice(0, 4).map((project) => <div key={project.id} className="flex items-center justify-between border-b border-slate-100 px-6 py-5 last:border-0"><div className="flex min-w-0 items-center gap-3"><div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600"><Code2 className="size-5" /></div><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-800">{project.name}</p><p className="truncate text-xs text-slate-400">{project.source}</p></div></div><div className="flex items-center gap-3"><Badge variant="secondary" className="hidden rounded-full bg-emerald-50 text-emerald-700 sm:inline-flex">{project.status}</Badge><ChevronRight className="size-4 text-slate-300" /></div></div>)}</CardContent></Card>
      <Card className="border-0 bg-slate-950 text-white shadow-[0_12px_40px_rgba(15,23,42,0.12)]"><CardHeader><div className="flex items-center justify-between"><div><CardTitle className="text-base text-white">Recent activity</CardTitle><p className="mt-1 text-xs text-slate-400">A traceable record of the workspace</p></div><Activity className="size-5 text-slate-500" /></div></CardHeader><CardContent className="space-y-5">{(data?.activity ?? []).length === 0 ? <p className="text-sm leading-6 text-slate-400">Activity will appear here as you inspect projects, create tasks, and run validations.</p> : data?.activity.slice(0, 5).map((item) => <div key={item.id} className="flex gap-3"><span className="mt-1 size-2 shrink-0 rounded-full bg-cyan-400" /><div><p className="text-sm leading-5 text-slate-200">{item.message}</p><p className="mt-1 text-[11px] text-slate-500">{new Date(item.createdAt).toLocaleString()}</p></div></div>)}</CardContent></Card>
    </div>
  </>;
}

function Projects() {
  const utils = trpc.useUtils(); const { data: projects = [], isLoading } = trpc.projects.list.useQuery(); const [name, setName] = useState(""); const [source, setSource] = useState(""); const [sourceContent, setSourceContent] = useState(""); const [archiveBase64, setArchiveBase64] = useState(""); const [archiveName, setArchiveName] = useState(""); const [archiveMime, setArchiveMime] = useState(""); const [sourceMode, setSourceMode] = useState<"link" | "file">("link"); const [uploadError, setUploadError] = useState(""); const create = trpc.projects.create.useMutation({ onSuccess: () => { setName(""); setSource(""); setSourceContent(""); setArchiveBase64(""); setArchiveName(""); setArchiveMime(""); setUploadError(""); utils.projects.list.invalidate(); utils.dashboard.summary.invalidate(); }, onError: (error) => setUploadError(error.message) }); const inspect = trpc.projects.inspect.useMutation({ onSuccess: () => { utils.projects.list.invalidate(); utils.dashboard.summary.invalidate(); } }); const remove = trpc.projects.remove.useMutation({ onSuccess: () => { utils.projects.list.invalidate(); utils.dashboard.summary.invalidate(); } });
  return <><SectionHeading eyebrow="Workspace inventory" title="Projects" description="Connect a repository or project path. The inspection engine records detected languages, frameworks, and dependencies for an auditable starting point." /><div className="mb-6 grid gap-6 xl:grid-cols-[0.8fr_1.2fr]"><Card className="border-0 bg-slate-950 text-white shadow-[0_12px_40px_rgba(15,23,42,0.12)]"><CardHeader><CardTitle className="text-base text-white">Connect a project</CardTitle><p className="text-xs leading-5 text-slate-400">Use a repository URL, local project path, or a descriptive source reference.</p></CardHeader><CardContent className="space-y-3"><Input value={name} onChange={(e) => setName(e.target.value)} placeholder="Project name" className="border-slate-800 bg-slate-900 text-white placeholder:text-slate-600" />{sourceMode === "link" ? <Input key={projectSourceInputKey("link")} value={source} onChange={(e) => setSource(e.target.value)} placeholder="github.com/org/repo or C:\\Projects\\app" className="border-slate-800 bg-slate-900 text-white placeholder:text-slate-600" /> : <Input key={projectSourceInputKey("file")} type="file" accept=".zip,.gz,.tgz,.txt,.md,.json,.ts,.tsx,.js,.jsx,.py,.go,.rs,.java,.cs,.html,.css,.yml,.yaml,.toml,.env.example" onChange={(e) => { const file = e.target.files?.[0]; setUploadError(""); setSource(file?.name ?? ""); setSourceContent(""); if (!file) return; const isArchive = /\.(zip|gz|tgz)$/i.test(file.name) || /zip|gzip|compressed|archive/i.test(file.type); const reader = new FileReader(); if (isArchive) { reader.onload = () => { const dataUrl = typeof reader.result === "string" ? reader.result : ""; setArchiveBase64(dataUrl.split(",")[1] ?? ""); setArchiveName(file.name); setArchiveMime(file.type || "application/octet-stream"); }; reader.onerror = () => setUploadError("The selected archive could not be read."); reader.readAsDataURL(file); return; } reader.onload = () => setSourceContent(typeof reader.result === "string" ? reader.result : ""); reader.onerror = () => setUploadError("The selected file could not be read as text."); reader.readAsText(file); }} className="border-slate-800 bg-slate-900 text-xs text-slate-300 file:mr-3 file:border-0 file:bg-cyan-400 file:px-3 file:py-1 file:text-xs file:font-semibold file:text-slate-950" />}
{uploadError && <p className="text-xs leading-5 text-amber-300">{uploadError}</p>}<div className="flex gap-2 text-[11px]"><button type="button" onClick={() => setSourceMode("link")} className={cn("rounded-full px-3 py-1", sourceMode === "link" ? "bg-slate-700 text-white" : "text-slate-500")}>Link or path</button><button type="button" onClick={() => setSourceMode("file")} className={cn("rounded-full px-3 py-1", sourceMode === "file" ? "bg-slate-700 text-white" : "text-slate-500")}>Upload reference</button></div><Button disabled={create.isPending || !name.trim() || !source.trim() || Boolean(uploadError)} onClick={() => create.mutate({ name: name.trim(), source: source.trim(), sourceContent: sourceContent || undefined, archiveBase64: archiveBase64 || undefined, archiveName: archiveName || undefined, archiveMime: archiveMime || undefined })} className="w-full bg-cyan-400 text-slate-950 hover:bg-cyan-300">{create.isPending ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Plus className="mr-2 size-4" />} Inspect project</Button></CardContent></Card><div className="grid gap-4 sm:grid-cols-2">{isLoading ? <LoadingCard /> : projects.map((project) => <Card key={project.id} className="border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardContent className="p-5"><div className="mb-5 flex items-start justify-between"><span className="flex size-10 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600"><FolderKanban className="size-5" /></span><Badge variant="secondary" className="rounded-full bg-emerald-50 text-emerald-700">{project.status}</Badge></div><h3 className="font-semibold text-slate-900">{project.name}</h3><p className="mt-1 truncate text-xs text-slate-400">{project.source}</p><div className="mt-5 flex flex-wrap gap-1.5">{listFromJson(project.languages).slice(0, 3).map((tag) => <Badge key={tag} variant="outline" className="rounded-full text-[11px]">{tag}</Badge>)}</div><div className="mt-4 flex items-center gap-4"><Button variant="ghost" size="sm" className="px-0 text-primary hover:bg-transparent" onClick={() => inspect.mutate({ projectId: project.id })}><RefreshCw className="mr-2 size-3.5" /> Re-inspect</Button><Button variant="ghost" size="sm" className="px-0 text-red-600 hover:bg-transparent hover:text-red-700" onClick={() => { if (window.confirm(`Delete ${project.name}? This cannot be undone.`)) remove.mutate({ projectId: project.id, confirm: true }); }}>Delete</Button></div></CardContent></Card>)}{!isLoading && projects.length === 0 && <div className="sm:col-span-2"><EmptyState icon={FolderKanban} title="Your project inventory is empty" body="Add your first project from the panel on the left." /></div>}</div></div></>;
}

function Tasks() {
  const utils = trpc.useUtils(); const { data: tasks = [] } = trpc.tasks.list.useQuery(); const { data: projects = [] } = trpc.projects.list.useQuery(); const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [assignee, setAssignee] = useState(""); const [projectId, setProjectId] = useState<number>(); const [selectedTaskId, setSelectedTaskId] = useState<number>(); const { data: detail } = trpc.tasks.detail.useQuery({ taskId: selectedTaskId ?? 0 }, { enabled: Boolean(selectedTaskId) }); const create = trpc.tasks.create.useMutation({ onSuccess: () => { setTitle(""); setDescription(""); setAssignee(""); utils.tasks.list.invalidate(); utils.dashboard.summary.invalidate(); } }); const update = trpc.tasks.updateStatus.useMutation({ onSuccess: () => { utils.tasks.list.invalidate(); utils.dashboard.summary.invalidate(); } }); const updateAssignee = trpc.tasks.updateAssignee.useMutation({ onSuccess: () => { utils.tasks.list.invalidate(); utils.tasks.detail.invalidate(); utils.dashboard.summary.invalidate(); } });
  return <><SectionHeading eyebrow="Execution system" title="Tasks" description="Turn engineering intent into accountable work. Track every task through the exact status pipeline: Pending → In Progress → Done." /><Card className="mb-6 border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardContent className="grid gap-3 p-5 md:grid-cols-[1fr_1.3fr_1fr_0.7fr_auto]"><Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Task title" /><Input value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Short description" /><Input value={assignee} onChange={(e) => setAssignee(e.target.value)} placeholder="Assign to" /><select value={projectId ?? ""} onChange={(e) => setProjectId(Number(e.target.value) || undefined)} className="h-10 rounded-md border border-slate-200 bg-white px-3 text-sm text-slate-600"><option value="">Project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><Button disabled={!title || !projectId || create.isPending} onClick={() => projectId && create.mutate({ projectId, title, description, assignee: assignee || undefined })}><Plus className="mr-2 size-4" /> Add task</Button></CardContent></Card><div className="grid gap-4 lg:grid-cols-3">{["Pending", "In Progress", "Done"].map((status) => <div key={status} className="rounded-2xl bg-slate-100/70 p-3"><div className="mb-3 flex items-center justify-between px-2"><div className="flex items-center gap-2"><span className={cn("size-2 rounded-full", status === "Pending" ? "bg-slate-400" : status === "In Progress" ? "bg-amber-500" : "bg-emerald-500")} /><h3 className="text-sm font-semibold text-slate-700">{status}</h3></div><span className="text-xs text-slate-400">{tasks.filter((task) => task.status === status).length}</span></div><div className="space-y-3">{tasks.filter((task) => task.status === status).map((task) => <Card key={task.id} className="border-0 bg-white shadow-sm"><CardContent className="p-4"><div className="mb-3 flex items-start justify-between gap-2"><h4 className="text-sm font-semibold leading-5 text-slate-800">{task.title}</h4><Badge variant="secondary" className={cn("rounded-full text-[10px]", statusColors[task.status])}>{task.priority}</Badge></div><p className="line-clamp-2 text-xs leading-5 text-slate-500">{task.description || "No description recorded."}</p><Button variant="ghost" size="sm" className="mt-2 h-7 px-0 text-[11px] text-primary hover:bg-transparent" onClick={() => setSelectedTaskId(task.id)}>View task detail <ChevronRight className="ml-1 size-3" /></Button><div className="mt-4 flex items-center justify-between"><span className="text-[11px] text-slate-400">{task.assignee || "Unassigned"}</span><select value={task.status} onChange={(e) => update.mutate({ taskId: task.id, status: e.target.value as "Pending" | "In Progress" | "Done" })} className="border-0 bg-transparent text-[11px] font-medium text-primary outline-none"><option>Pending</option><option>In Progress</option><option>Done</option></select></div></CardContent></Card>)}</div></div>)}</div>{detail && <Card className="mt-6 border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle className="text-base">Task detail</CardTitle><p className="mt-1 text-xs text-slate-400">{detail.task.title}</p></div><Button variant="ghost" size="sm" onClick={() => setSelectedTaskId(undefined)}>Close</Button></CardHeader><CardContent><div className="mb-5 flex flex-wrap items-center gap-2"><Badge variant="secondary" className={cn("rounded-full", statusColors[detail.task.status])}>{detail.task.status}</Badge><span className="text-xs text-slate-500">Assigned to {detail.task.assignee || "Unassigned"}</span><Input className="ml-auto max-w-48" defaultValue={detail.task.assignee ?? ""} placeholder="Reassign to" onBlur={(e) => updateAssignee.mutate({ taskId: detail.task.id, assignee: e.target.value || null })} /></div>{detail.changes.length === 0 ? <p className="text-sm text-slate-500">No proposed code changes are attached to this task.</p> : detail.changes.map(({ change, events }) => <div key={change.id} className="space-y-3"><div className="flex items-center justify-between"><p className="text-sm font-semibold text-slate-800">{change.summary}</p><Badge variant="outline" className="rounded-full">{change.status}</Badge></div><pre className="max-h-56 overflow-auto rounded-xl bg-slate-950 p-4 text-xs leading-6 text-slate-300">{change.diff}</pre><div className="space-y-1">{events.map((event) => <p key={event.id} className="text-[11px] text-slate-400">{event.action} · {new Date(event.createdAt).toLocaleString()} · {event.note}</p>)}</div></div>)}</CardContent></Card>}</>;
}

function Changes() { const utils = trpc.useUtils(); const { data: changes = [] } = trpc.changes.list.useQuery(); const review = trpc.changes.review.useMutation({ onSuccess: () => utils.changes.list.invalidate() }); return <><SectionHeading eyebrow="Review queue" title="Code changes" description="Inspect proposed diffs before they become part of the codebase. Every decision is recorded as Applied or Rejected." />{changes.length === 0 ? <EmptyState icon={Code2} title="No proposed code changes" body="Create a task with a proposed diff to start the review queue." /> : <div className="space-y-4">{changes.map(({ change, task }) => <Card key={change.id} className="border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardContent className="p-6"><div className="flex flex-col justify-between gap-4 lg:flex-row"><div><div className="mb-2 flex items-center gap-2"><Badge variant="outline" className="rounded-full">{change.status}</Badge><span className="text-xs text-slate-400">Task #{task.id}</span></div><h3 className="font-semibold text-slate-900">{change.summary}</h3></div><div className="flex gap-2"><Button size="sm" className="bg-emerald-600 hover:bg-emerald-700" disabled={change.status !== "Proposed"} onClick={() => review.mutate({ changeId: change.id, status: "Applied" })}><CheckCircle2 className="mr-2 size-4" /> Apply</Button><Button size="sm" variant="outline" className="text-red-600" disabled={change.status !== "Proposed"} onClick={() => review.mutate({ changeId: change.id, status: "Rejected" })}><XCircle className="mr-2 size-4" /> Reject</Button></div></div><pre className="mt-5 max-h-72 overflow-auto rounded-xl bg-slate-950 p-4 text-xs leading-6 text-slate-300">{change.diff}</pre></CardContent></Card>)}</div>}</> }

function Audits() { const utils = trpc.useUtils(); const { data: projects = [] } = trpc.projects.list.useQuery(); const { data: audits = [] } = trpc.audits.list.useQuery(); const [projectId, setProjectId] = useState<number>(); const run = trpc.audits.run.useMutation({ onSuccess: () => { utils.audits.list.invalidate(); utils.dashboard.summary.invalidate(); } }); return <><SectionHeading eyebrow="Risk surface" title="Security audit" description="Run rule-based checks against recorded project metadata and keep findings visible by severity. Full source scans require project content or an authorized runner." action={<div className="flex gap-2"><select value={projectId ?? ""} onChange={(e) => setProjectId(Number(e.target.value) || undefined)} className="h-10 rounded-md border border-slate-200 bg-white px-3 text-sm"><option value="">Select project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><Button disabled={!projectId || run.isPending} onClick={() => projectId && run.mutate({ projectId })}><ShieldAlert className="mr-2 size-4" /> Run audit</Button></div>} />{audits.length === 0 ? <EmptyState icon={ShieldAlert} title="No audits recorded" body="Select a project to run the first rule-based security audit." /> : <div className="space-y-4">{audits.map(({ audit, findings }) => <Card key={audit.id} className="border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle className="text-base">Audit #{audit.id}</CardTitle><p className="mt-1 text-xs text-slate-400">{new Date(audit.createdAt).toLocaleString()}</p></div><Badge variant="secondary" className="rounded-full bg-emerald-50 text-emerald-700">{audit.status}</Badge></CardHeader><CardContent><p className="mb-4 text-sm leading-6 text-slate-500">{audit.summary}</p>{findings.length === 0 ? <div className="rounded-xl border border-dashed border-emerald-200 bg-emerald-50/50 p-4 text-sm text-emerald-800">No rule matches were recorded. Full source verification is still NOT VERIFIED without project content.</div> : findings.map((finding) => <div key={finding.id} className="mb-3 flex items-start gap-3 rounded-xl border border-slate-100 p-4"><Badge variant="secondary" className={cn("rounded-full", severityColors[finding.severity])}>{finding.severity}</Badge><div><p className="text-sm font-semibold text-slate-800">{finding.title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{finding.detail}</p></div></div>)}</CardContent></Card>)}</div>}</> }

  function Automation() { const utils = trpc.useUtils(); const { data: projects = [] } = trpc.projects.list.useQuery(); const { data: scripts = [] } = trpc.scripts.list.useQuery(); const { data: runs = [] } = trpc.scripts.runs.useQuery(undefined, { refetchInterval: 2500 }); const { data: executionApprovals = [] } = trpc.approvals.list.useQuery(undefined, { refetchInterval: 2500 }); const [projectId, setProjectId] = useState<number>(); const [name, setName] = useState(""); const [shell, setShell] = useState<"PowerShell" | "Shell">("PowerShell"); const [content, setContent] = useState("# Add a safe, reviewable script\nWrite-Host 'Connect an authorized runner to execute this script'"); const [runError, setRunError] = useState(""); const [runFilter, setRunFilter] = useState<"All" | "Pending" | "In Progress" | "Done" | "Error" | "Not Verified">("All"); const create = trpc.scripts.create.useMutation({ onSuccess: () => { setName(""); utils.scripts.list.invalidate(); } }); const run = trpc.scripts.run.useMutation({ onSuccess: () => { setRunError(""); utils.scripts.runs.invalidate(); }, onError: (error) => setRunError(error.message) });   const runLifecycle = (status: string) => status === "Requested" ? "Pending" : status === "Running" ? "In Progress" : status === "Passed" ? "Done" : status === "Failed" ? "Error" : status === "Not Verified" ? "Not Verified" : "Pending"; const runStatusClass = (status: string) => status === "Done" ? "bg-emerald-50 text-emerald-700" : status === "Error" ? "bg-red-50 text-red-700" : status === "In Progress" ? "bg-amber-50 text-amber-800" : status === "Not Verified" ? "bg-violet-50 text-violet-700" : "bg-slate-100 text-slate-700"; const visibleRuns = useMemo(() => runs.filter((item) => runFilter === "All" || runLifecycle(item.status) === runFilter).slice(0, 12), [runs, runFilter]); const exportRuns = () => { const blob = new Blob([JSON.stringify(visibleRuns, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "automation-run-log.json"; anchor.click(); URL.revokeObjectURL(url); }; return <><SectionHeading eyebrow="Controlled automation" title="PowerShell / shell automation" description="Save a reviewable script, then press Run when you want an execution request. An authorized runner reports live status and output; without one, the run is recorded as Not Verified." /><div className="grid w-full min-w-0 max-w-full gap-6 overflow-hidden xl:grid-cols-[0.8fr_1.2fr]"><Card className="w-full min-w-0 max-w-full overflow-hidden border-0 bg-slate-950 text-white shadow-[0_12px_40px_rgba(15,23,42,0.12)]"><CardHeader><CardTitle className="text-base text-white">New script</CardTitle></CardHeader><CardContent className="space-y-3"><Input value={name} onChange={(e) => setName(e.target.value)} placeholder="Script name" className="w-full min-w-0 border-slate-800 bg-slate-900 text-white placeholder:text-slate-600" /><select value={shell} onChange={(e) => setShell(e.target.value as typeof shell)} className="h-10 w-full rounded-md border border-slate-800 bg-slate-900 px-3 text-sm text-slate-300"><option>PowerShell</option><option>Shell</option></select><select value={projectId ?? ""} onChange={(e) => setProjectId(Number(e.target.value) || undefined)} className="h-10 w-full rounded-md border border-slate-800 bg-slate-900 px-3 text-sm text-slate-300"><option value="">Project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><Textarea value={content} onChange={(e) => setContent(e.target.value)} className="min-h-36 w-full min-w-0 border-slate-800 bg-slate-900 font-mono text-xs text-slate-200" /><Button disabled={!name || !projectId || create.isPending} onClick={() => projectId && create.mutate({ projectId, name, shell, content })} className="w-full bg-cyan-400 text-slate-950 hover:bg-cyan-300"><Plus className="mr-2 size-4" /> Save script</Button></CardContent></Card><div className="space-y-4">{scripts.map((script) => <Card key={script.id} className="border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardContent className="flex items-center justify-between gap-4 p-5"><div className="flex min-w-0 items-center gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-slate-100"><Terminal className="size-5 text-slate-700" /></span><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-800">{script.name}</p><p className="text-xs text-slate-400">{script.shell} · saved script</p></div></div><Button size="sm" variant="outline" disabled={run.isPending} onClick={() => run.mutate({ scriptId: script.id })}><Play className="mr-2 size-3.5" /> {run.isPending ? "Requesting..." : "Run"}</Button></CardContent></Card>)}{runError && <div className="rounded-xl border border-red-200 bg-red-50 p-3 text-xs leading-5 text-red-700"><p className="font-semibold">Run request error</p><p className="mt-1">{runError}</p></div>}{scripts.length === 0 && <EmptyState icon={Terminal} title="No scripts stored" body="Save a PowerShell or shell script to create a controlled automation catalog." />}<Card className="border-0 bg-slate-900 text-slate-100"><CardHeader><div className="flex items-center justify-between gap-3"><CardTitle className="flex items-center gap-2 text-sm"><Activity className="size-4 text-cyan-300" /> Live output log</CardTitle><Button size="sm" variant="outline" onClick={exportRuns} disabled={visibleRuns.length === 0} className="border-slate-700 text-[10px] text-slate-300">Export JSON</Button></div><p className="mt-1 text-xs text-slate-500">Lifecycle: Pending → In Progress → Done, Error, or Not Verified. Not Verified means no authorized runner completed the request.</p><div className="mt-3 flex flex-wrap items-center gap-2"><label htmlFor="automation-log-filter" className="text-[10px] uppercase tracking-[0.16em] text-slate-500">Filter</label><select id="automation-log-filter" value={runFilter} onChange={(e) => setRunFilter(e.target.value as typeof runFilter)} className="h-8 rounded-md border border-slate-700 bg-slate-950 px-2 text-[11px] text-slate-300"><option>All</option><option>Pending</option><option>In Progress</option><option>Done</option><option>Error</option><option>Not Verified</option></select></div><div className="mt-3 rounded-lg border border-cyan-400/20 bg-cyan-400/5 p-3 text-[11px] leading-5 text-slate-400"><p className="font-semibold text-cyan-100">Authorized runner setup</p><p className="mt-1">Save aur Run request yahan hoti hai. Real command execution ke liye registered Active runner chahiye; runner connect na ho to status Not Verified rahega.</p></div></CardHeader><CardContent className="space-y-3">{executionApprovals.filter((request) => request.kind === "Script" && ["Requested", "Running"].includes(request.status)).map((request) => <div key={`approval-${request.id}`} className="rounded-lg border border-cyan-400/20 bg-cyan-400/5 p-3"><div className="flex items-center justify-between gap-3"><p className="text-xs text-cyan-100">Runner request #{request.id}</p><Badge variant="secondary" className={cn("rounded-full text-[10px]", runStatusClass(runLifecycle(request.status)))}>{runLifecycle(request.status)}</Badge></div><p className="mt-1 text-[11px] text-slate-400">Authorized runner response ka intezar hai.</p></div>)}{visibleRuns.length === 0 ? <p className="font-mono text-xs text-slate-500">{runs.length === 0 ? "Output will appear after a script run request." : "No runs match this filter."}</p> : visibleRuns.map((item) => <div key={item.id} className="rounded-lg bg-slate-950 p-3"><div className="mb-2 flex items-center justify-between gap-3"><p className="text-[11px] text-slate-400">Run #{item.id} · {new Date(item.startedAt).toLocaleString()}</p><Badge variant="secondary" className={cn("rounded-full text-[10px]", runStatusClass(runLifecycle(item.status)))}>{runLifecycle(item.status)}</Badge></div><pre className="whitespace-pre-wrap font-mono text-xs leading-5 text-slate-400">{item.output || "Waiting for runner output..."}</pre></div>)}</CardContent></Card></div></div></> }

function Testing() { const utils = trpc.useUtils(); const { data: projects = [] } = trpc.projects.list.useQuery(); const { data: runs = [] } = trpc.tests.list.useQuery(); const [projectId, setProjectId] = useState<number>(); const [suiteName, setSuiteName] = useState("Full test suite"); const run = trpc.tests.run.useMutation({ onSuccess: () => { utils.tests.list.invalidate(); utils.dashboard.summary.invalidate(); } }); return <><SectionHeading eyebrow="Verification layer" title="Testing" description="Record test-suite requests, pass/fail results, and coverage summaries without presenting unexecuted work as successful." action={<div className="flex gap-2"><select value={projectId ?? ""} onChange={(e) => setProjectId(Number(e.target.value) || undefined)} className="h-10 rounded-md border border-slate-200 bg-white px-3 text-sm"><option value="">Select project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><Button disabled={!projectId} onClick={() => projectId && run.mutate({ projectId, suiteName })}><Play className="mr-2 size-4" /> Run tests</Button></div>} /><div className="mb-6 flex max-w-xl gap-3"><Input value={suiteName} onChange={(e) => setSuiteName(e.target.value)} placeholder="Suite name" /></div><div className="grid gap-4 md:grid-cols-2">{runs.map((item) => <Card key={item.id} className="border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardContent className="p-5"><div className="flex items-start justify-between"><div><p className="text-sm font-semibold text-slate-800">{item.suiteName}</p><p className="mt-1 text-xs text-slate-400">{new Date(item.createdAt).toLocaleString()}</p></div><Badge variant="secondary" className="rounded-full bg-slate-100 text-slate-700">{item.status}</Badge></div><div className="mt-5 grid grid-cols-3 gap-2"><div className="rounded-xl bg-emerald-50 p-3"><p className="text-lg font-semibold text-emerald-700">{item.passed}</p><p className="text-[10px] text-emerald-600">Passed</p></div><div className="rounded-xl bg-red-50 p-3"><p className="text-lg font-semibold text-red-700">{item.failed}</p><p className="text-[10px] text-red-600">Failed</p></div><div className="rounded-xl bg-slate-100 p-3"><p className="text-lg font-semibold text-slate-700">{item.coverage ?? "—"}</p><p className="text-[10px] text-slate-500">Coverage</p></div></div><pre className="mt-4 whitespace-pre-wrap text-xs leading-5 text-slate-400">{item.output}</pre></CardContent></Card>)}{runs.length === 0 && <div className="md:col-span-2"><EmptyState icon={TestTube2} title="No test runs recorded" body="Run a suite request to create a traceable verification record." /></div>}</div></> }

function makePdf(markdown: string) {
  const lines = markdown.replace(/[#*_`]/g, "").split("\n").flatMap((line) => line.match(/.{1,92}/g) ?? [""]).slice(0, 48);
  const content = ["BT", "/F1 10 Tf", "50 760 Td", ...lines.flatMap((line, index) => [`(${line.replace(/\\/g, "\\\\").replace(/[()]/g, "\\$&")}) Tj`, index < lines.length - 1 ? "0 -15 Td" : ""]), "ET"].join("\n");
  const objects = ["<< /Type /Catalog /Pages 2 0 R >>", "<< /Type /Pages /Kids [3 0 R] /Count 1 >>", "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>", "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>", `<< /Length ${content.length} >>\nstream\n${content}\nendstream`];
  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  for (let index = 0; index < objects.length; index += 1) { offsets.push(pdf.length); pdf += `${index + 1} 0 obj\n${objects[index]}\nendobj\n`; }
  const xref = pdf.length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.slice(1).map((offset) => `${String(offset).padStart(10, "0")} 00000 n \n`).join("")}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  return new Blob([pdf], { type: "application/pdf" });
}

function Reports() { const utils = trpc.useUtils(); const { data: projects = [] } = trpc.projects.list.useQuery(); const { data: reports = [] } = trpc.reports.list.useQuery(); const [projectId, setProjectId] = useState<number>(); const [type, setType] = useState<"Inspection" | "Audit" | "Testing">("Inspection"); const generate = trpc.reports.generate.useMutation({ onSuccess: () => utils.reports.list.invalidate() }); const download = (content: string, filename: string, type: string) => { const url = URL.createObjectURL(new Blob([content], { type })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }; return <><SectionHeading eyebrow="Evidence archive" title="Engineering reports" description="Generate structured Markdown reports from recorded inspection, audit, and testing data. PDF export remains available through the browser’s print-to-PDF workflow." action={<div className="flex gap-2"><select value={projectId ?? ""} onChange={(e) => setProjectId(Number(e.target.value) || undefined)} className="h-10 rounded-md border border-slate-200 bg-white px-3 text-sm"><option value="">Select project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><select value={type} onChange={(e) => setType(e.target.value as typeof type)} className="h-10 rounded-md border border-slate-200 bg-white px-3 text-sm"><option>Inspection</option><option>Audit</option><option>Testing</option></select><Button disabled={!projectId || generate.isPending} onClick={() => projectId && generate.mutate({ projectId, type })}><FileText className="mr-2 size-4" /> Generate</Button></div>} /><div className="space-y-4">{reports.map((report) => <Card key={report.id} className="border-0 bg-white shadow-[0_12px_40px_rgba(15,23,42,0.06)]"><CardContent className="flex flex-col justify-between gap-4 p-5 md:flex-row md:items-center"><div><div className="flex items-center gap-2"><Badge variant="outline" className="rounded-full">{report.type}</Badge><span className="text-xs text-slate-400">{new Date(report.createdAt).toLocaleString()}</span></div><h3 className="mt-2 font-semibold text-slate-800">{report.title}</h3></div><div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => download(report.markdown, `${report.title}.md`, "text/markdown")}>Markdown</Button><Button size="sm" onClick={() => { const url = URL.createObjectURL(makePdf(report.markdown)); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${report.title}.pdf`; anchor.click(); URL.revokeObjectURL(url); }}><FileText className="mr-2 size-3.5" /> PDF</Button></div></CardContent></Card>)}{reports.length === 0 && <EmptyState icon={FileText} title="No reports generated" body="Generate an Inspection, Audit, or Testing report for a selected project." />}</div></> }

type ChatMessage = { role: "user" | "assistant"; content: string };
function Assistant() {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [buildPrompt, setBuildPrompt] = useState("");
  const [lastBuildPrompt, setLastBuildPrompt] = useState("");
  const [projectId, setProjectId] = useState<number>();
  const [showLatestProposal, setShowLatestProposal] = useState(false);
  const [buildError, setBuildError] = useState("");
  const [chatError, setChatError] = useState("");
  const [executionFeedback, setExecutionFeedback] = useState("");
  const [executionMode, setExecutionMode] = useState<"runner" | "self">("self");
  const [generationMode, setGenerationMode] = useState<"free" | "local" | "model">("free");
  const [targetId, setTargetId] = useState<UniversalTargetId>("windows-powershell");
  const [projectType, setProjectType] = useState("General software");
  const [runtime, setRuntime] = useState("");
  const [permissionLevel, setPermissionLevel] = useState<PermissionLevel>("standard");
  const [targetConfirmed, setTargetConfirmed] = useState(false);
  const [pathUnknown, setPathUnknown] = useState(false);
  const [discoveryOs, setDiscoveryOs] = useState<DiscoveryOs>("Windows");
  const [discoveredPath, setDiscoveredPath] = useState("");
  const [discoveryOutput, setDiscoveryOutput] = useState("");
  const [pathConfirmed, setPathConfirmed] = useState(false);
  const [aclOutput, setAclOutput] = useState("");
  const [historySuppressed, setHistorySuppressed] = useState(false);
  const utils = trpc.useUtils();
  const { data: projects = [] } = trpc.projects.list.useQuery();
  const { data: assistantHistory = [] } = trpc.assistant.history.useQuery(projectId ? { projectId } : undefined);
  const recentAssistantHistory = assistantHistory.slice(-8);
  const { data: proposals = [] } = trpc.builder.list.useQuery();
  const { data: executionApprovals = [] } = trpc.approvals.list.useQuery();
  const chat = trpc.assistant.chat.useMutation({ onSuccess: ({ answer }) => { setChatError(""); setMessages((current) => [...current, { role: "assistant", content: answer }]); }, onError: (error) => { const safe = error.message.includes("Too big") ? "Yeh pasted feedback bohot lamba tha. Aapki visible chat saved hai; isay chhote hisson mein bhejein." : "Assistant response generate nahi ho saki, lekin chat screen safe hai. Error ko dobara short feedback ke saath try karein."; setChatError(safe); setMessages((current) => [...current, { role: "assistant", content: safe }]); } });
  useEffect(() => {
    if (!historySuppressed && messages.length === 0 && assistantHistory.length > 0) {
      setMessages(recentAssistantHistory.map((item) => ({ role: item.role, content: item.content })));
    }
  }, [recentAssistantHistory, historySuppressed, messages.length]);
  const build = trpc.builder.generate.useMutation({ onSuccess: () => { setBuildPrompt(""); setBuildError(""); setShowLatestProposal(true); }, onError: (error) => { setBuildError(friendlyBuilderError(error.message)); setShowLatestProposal(false); } });
  const createProject = trpc.projects.create.useMutation();
  const createScript = trpc.scripts.create.useMutation();
  const runScript = trpc.scripts.run.useMutation();
  const [runnerStatus, setRunnerStatus] = useState("");
  const [runnerConfirm, setRunnerConfirm] = useState(false);
  const review = trpc.builder.review.useMutation({ onSuccess: () => { utils.builder.list.invalidate(); utils.approvals.list.invalidate(); setShowLatestProposal(false); setExecutionFeedback(""); } });
  const generationContext = { targetId, projectType, runtime: runtime.trim() || undefined, permissionLevel, targetConfirmed };
  const handleSend = (content: string) => {
    const clean = content.trim();
    if (!clean) return;
    const next = [...messages, { role: "user" as const, content: clean }];
    setMessages(next);
    setHistorySuppressed(false);
    setChatError("");
    const modelContent = looksLikeTerminalTranscript(clean) ? terminalFeedbackPrompt(clean) : clean;
    const modelMessages = [...messages, { role: "user" as const, content: modelContent }];
    chat.mutate({ messages: compactChatForTransport(modelMessages), projectId });
    if (isSoftwareBuildIntent(clean)) {
      setBuildPrompt(clean);
      setLastBuildPrompt(clean);
      setBuildError("");
      setShowLatestProposal(false);
      build.mutate({ prompt: trimForTransport([buildUniversalGenerationContract(generationContext), buildExecutionInstructions(executionMode, pathUnknown && !pathConfirmed, discoveredPath, discoveryOs), clean].filter(Boolean).join("\n\n"), 28000), projectId, generationMode, context: generationContext });
    }
  };
  const latest = showLatestProposal ? (build.data ?? proposals[0]) : undefined;
  const pendingCount = proposals.filter((proposal) => proposal.status === "Proposed").length + executionApprovals.filter((request) => ["Requested", "Running"].includes(request.status)).length;
  const reviewHistory = proposals.filter((proposal) => proposal.status !== "Proposed").slice(0, 8);
  const parsedPaths = parsePowerShellPaths(discoveryOutput);
  const inferredFolderName = inferFolderName(buildPrompt);
  const protectionRecommendation = recommendProtection(buildPrompt, discoveryOs);
  const parsedAclAccounts = parseAclAccounts(aclOutput);

  const proposalPrompt = [buildUniversalGenerationContract(generationContext), buildExecutionInstructions(executionMode, pathUnknown && !pathConfirmed, discoveredPath, discoveryOs), buildPrompt].filter(Boolean).join("\n\n");
  const continueBuildStage = () => {
    const base = lastBuildPrompt.trim();
    if (!base) { setRunnerStatus("Pehle Assistant mein software prompt dein."); return; }
    const continuation = `${base}\n\nContinue with the next executable stage. Keep the existing product brief as context, implement only the next user-visible vertical slice, return complete files and PowerShell save/run commands, and list remaining modules for later stages.`;
    setBuildPrompt(continuation);
    setBuildError("");
    setShowLatestProposal(false);
    build.mutate({ prompt: trimForTransport([buildUniversalGenerationContract(generationContext), buildExecutionInstructions(executionMode, pathUnknown && !pathConfirmed, discoveredPath, discoveryOs), continuation].filter(Boolean).join("\n\n"), 28000), projectId, generationMode, context: generationContext });
  };
  const startNewChat = () => { setMessages([]); setHistorySuppressed(true); setRunnerStatus("New chat start ho gayi. Purani saved chat delete nahi hui; Restore history se wapas la sakte hain."); };
  const restoreChatHistory = () => { setHistorySuppressed(false); setMessages(recentAssistantHistory.map((item) => ({ role: item.role, content: item.content }))); setRunnerStatus(assistantHistory.length > recentAssistantHistory.length ? `Recent ${recentAssistantHistory.length} messages restore hui hain; purani history saved hai.` : assistantHistory.length ? "Saved Assistant history restore ho gayi." : "Is account ke liye saved Assistant history nahi mili."); };
  const resetBuilder = () => { setBuildPrompt(""); setLastBuildPrompt(""); setProjectId(undefined); setBuildError(""); setExecutionFeedback(""); setRunnerStatus(""); setRunnerConfirm(false); setShowLatestProposal(false); setExecutionMode("self"); setGenerationMode("free"); setTargetId("windows-powershell"); setProjectType("General software"); setRuntime(""); setPermissionLevel("standard"); setTargetConfirmed(false); setPathUnknown(false); setDiscoveryOs("Windows"); setDiscoveredPath(""); setDiscoveryOutput(""); setPathConfirmed(false); setAclOutput(""); };
  const submitExecutionFeedback = () => { const feedback = executionFeedback.trim(); if (!feedback) return; handleSend(`Execution feedback for the latest Builder proposal: ${feedback}`); setExecutionFeedback(""); };
  const copyCommands = async (commands: string[]) => { await navigator.clipboard?.writeText(commands.join("\n")); };
  const copyFileContent = async (content: string) => { await navigator.clipboard?.writeText(content); };
  const downloadFileContent = (path: string, content: string) => { const url = URL.createObjectURL(new Blob([content], { type: "text/plain;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = path.split(/[\\/]/).pop() || "generated-file.txt"; anchor.click(); URL.revokeObjectURL(url); };
  const discoverFolderOnRunner = async () => {
    if (!projectId) { setRunnerStatus("Auto-discovery ke liye pehle project context select karein."); return; }
    if (!inferredFolderName) { setRunnerStatus("Prompt mein folder ka naam likhein, misal: Final Leads folder."); return; }
    try {
      setRunnerStatus(`${inferredFolderName} folder ko connected runner par read-only dhoonda ja raha hai...`);
      const content = discoveryOs === "Windows"
        ? `$matches = Get-ChildItem -Path $HOME -Directory -Filter '${inferredFolderName.replace(/'/g, "''")}' -Recurse -ErrorAction SilentlyContinue; $matches | Select-Object -ExpandProperty FullName`
        : `find "$HOME" -type d -name '${inferredFolderName.replace(/'/g, "'\\''")}' -print 2>/dev/null`;
      const created = await createScript.mutateAsync({ projectId, name: `Discover-${inferredFolderName.replace(/[^A-Za-z0-9_-]/g, "-")}-${Date.now()}.ps1`, shell: discoveryOs === "Windows" ? "PowerShell" : "Shell", content });
      const run = await runScript.mutateAsync({ scriptId: created.id });
      const output = run.output ?? "";
      setDiscoveryOutput(output);
      const paths = parsePowerShellPaths(output);
      if (paths.length === 1) setDiscoveredPath(paths[0]);
      setRunnerStatus(`${run.status}: ${paths.length} candidate path${paths.length === 1 ? "" : "s"} found.`);
    } catch (error) { setRunnerStatus(error instanceof Error ? error.message : "Folder discovery request failed."); }
  };
  const sendToAutoRunner = async () => {
    if (!runnerConfirm) { setRunnerConfirm(true); setRunnerStatus("Review complete? Confirm karein; is ke baad generated build package authorized runner ko bheja jayega."); return; }
    if (!latest || !Array.isArray(latest.files) || latest.files.length === 0) { setRunnerStatus("Execution ke liye generated files abhi available nahi hain."); return; }
    try {
      setRunnerStatus("Build workspace aur runner package prepare ho raha hai...");
      let targetProjectId = projectId;
      if (!targetProjectId) {
        const workspaceName = `SynapseX Generated Workspace ${new Date().toLocaleDateString()}`;
        const generated = await createProject.mutateAsync({ name: workspaceName, source: "synapsex://generated-workspace", description: "Assistant-generated workspace; files are created only through an authorized runner." });
        targetProjectId = generated.id;
        setProjectId(targetProjectId);
        utils.projects.list.invalidate();
      }
      const workspaceSlug = `synapsex-${Date.now()}`;
      const content = `$workspace = Join-Path $HOME "SynapseX-Workspaces\\${workspaceSlug}"\nNew-Item -ItemType Directory -Force -Path $workspace | Out-Null\nSet-Location -LiteralPath $workspace\n` + latest.files.map((file: { path?: string; content?: string }) => { const relative = (file.path ?? "generated.txt").replace(/^[\\/]+/, ""); return `$target = Join-Path $workspace '${relative.replace(/'/g, "''")}'\nNew-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null\n@'\n${file.content ?? ""}\n'@ | Set-Content -LiteralPath $target -Encoding UTF8`; }).join("\n\n") + `\n\n${(Array.isArray(latest.commands) ? latest.commands : parse(latest.commands as string)).join("\n")}`;
      const created = await createScript.mutateAsync({ projectId: targetProjectId, name: `Build-${workspaceSlug}.ps1`, shell: "PowerShell", content });
      const run = await runScript.mutateAsync({ scriptId: created.id });
      setRunnerStatus(`${run.status}: ${run.output ?? "Build execution request recorded."}`);
    } catch (error) { setRunnerStatus(error instanceof Error ? error.message : "Authorized build execution request failed."); }
  };
  const downloadProposal = (proposal: typeof latest) => {
    if (!proposal) return;
    const url = URL.createObjectURL(new Blob([JSON.stringify(proposal, null, 2)], { type: "application/json" }));
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `engineering-proposal-${proposal.id}.json`;
    anchor.click();
    URL.revokeObjectURL(url);
  };
  const parse = (value: string | null | undefined, fallback: unknown[] = []) => {
    try { return value ? JSON.parse(value) : fallback; } catch { return fallback; }
  };

  return (
    <div className="flex h-[100dvh] min-h-0 flex-col overflow-hidden overflow-x-hidden rounded-2xl border border-slate-700 bg-[#101719] p-2 pt-16 text-slate-100 md:p-3 md:pt-3">
      <div className="shrink-0 px-2 pb-2">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="mb-1 text-[10px] font-semibold uppercase tracking-[0.18em] text-cyan-300">SynapseX command center</p><h1 className="text-lg font-semibold leading-tight tracking-[-0.03em] text-slate-100 sm:text-xl md:text-2xl">PowerShell Engineering Studio</h1></div><div className="flex gap-2"><Button type="button" size="sm" variant="outline" onClick={startNewChat} className="border-slate-700 bg-slate-950/60 text-[11px] text-slate-300">New chat</Button><Button type="button" size="sm" variant="outline" onClick={restoreChatHistory} disabled={!assistantHistory.length} className="border-cyan-400/30 bg-slate-950/60 text-[11px] text-cyan-200">Restore history</Button></div></div>
      </div>
      {chatError && <div className="mb-2 shrink-0 rounded-xl border border-amber-300/30 bg-amber-300/10 px-3 py-2 text-xs text-amber-100">{chatError}</div>}
      <div className="grid min-h-0 flex-1 gap-3 overflow-y-auto rounded-xl xl:grid-cols-[minmax(0,1.05fr)_minmax(420px,0.95fr)] xl:overflow-hidden">
        <AIChatBox
          className="h-[62vh] min-h-[420px] rounded-xl border-slate-700 bg-[#0d1517] text-slate-100 xl:h-full xl:min-h-0"
          messages={[{ role: "system", content: "" }, ...messages]}
          onSendMessage={handleSend}
          isLoading={chat.isPending}
          height="100%"
          emptyStateMessage="Isi Assistant screen par sawal poochein, software banwane ka prompt dein, files/diffs review karein, tests dekhein, aur approval ke baad authorized runner ya self-run commands choose karein."
          suggestedPrompts={["Mere liye ek professional real-estate marketing website banao", "Mere existing project ka bug analyze karke reviewed fix propose karo", "Mere liye Python invoice automation tool banao"]}
        />
      </div>
      <section className="min-h-[280px] overflow-hidden rounded-xl border border-slate-700 bg-slate-950 text-white shadow-[0_16px_42px_rgba(0,0,0,0.22)] xl:min-h-0">
        <div className="border-b border-slate-800 px-5 py-3 text-sm font-semibold text-cyan-200">Build inside Assistant <span className="ml-2 text-[10px] font-normal text-slate-400">{pendingCount} pending approval{pendingCount === 1 ? "" : "s"}</span></div>
        <div className="max-h-[70vh] overflow-y-auto p-5">
          <div className="rounded-xl border border-cyan-400/20 bg-cyan-400/5 p-3 text-xs leading-5 text-slate-300"><p className="font-semibold text-cyan-200">Assistant se software banwayein</p><p className="mt-1">Website, mobile app, desktop tool, API, automation ya kisi bhi codebase ka goal likhein. Assistant build package, complete files, commands, verification aur preview steps tayar karega. AutoRunner mein ek approval ke baad package connected runner par execute hoga; Self-run mein files aur commands milengi. System execution ka false claim nahi karta.</p></div><div className="hidden mt-3 rounded-xl border border-slate-800 bg-slate-900 p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Pending approvals</p>{proposals.filter((proposal) => proposal.status === "Proposed").length === 0 && executionApprovals.filter((request) => ["Requested", "Running"].includes(request.status)).length === 0 ? <p className="mt-2 text-xs text-slate-500">No pending proposals or runner actions.</p> : <div className="mt-2 space-y-2">{proposals.filter((proposal) => proposal.status === "Proposed").map((proposal) => <div key={`proposal-${proposal.id}`} className="flex items-center justify-between gap-3 rounded-lg bg-slate-950 px-3 py-2"><div className="min-w-0"><p className="truncate text-xs text-slate-200">Proposal #{proposal.id}</p><p className="text-[10px] text-slate-500">Next actor: user or authorized runner · Updated {new Date(proposal.updatedAt).toLocaleString()}</p></div><Badge variant="outline" className="shrink-0 rounded-full border-slate-700 text-[10px] text-slate-300">{proposal.status}</Badge></div>)}{executionApprovals.filter((request) => ["Requested", "Running"].includes(request.status)).map((request) => <div key={`execution-${request.id}`} className="flex items-center justify-between gap-3 rounded-lg bg-slate-950 px-3 py-2"><div className="min-w-0"><p className="truncate text-xs text-slate-200">{request.kind} runner request #{request.id}</p><p className="text-[10px] text-slate-500">Next actor: authorized runner · {new Date(request.updatedAt).toLocaleString()}</p></div><Badge variant="outline" className="shrink-0 rounded-full border-slate-700 text-[10px] text-slate-300">{request.status}</Badge></div>)}</div>}          </div>
          <div className="hidden mt-3 rounded-xl border border-slate-800 bg-slate-900 p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Review history</p>{reviewHistory.length === 0 ? <p className="mt-2 text-xs text-slate-500">Approved or rejected proposal decisions will appear here.</p> : <div className="mt-2 space-y-2">{reviewHistory.map((proposal) => <div key={`history-${proposal.id}`} className="rounded-lg bg-slate-950 px-3 py-2"><div className="flex items-center justify-between gap-3"><p className="text-xs text-slate-200">Proposal #{proposal.id}</p><Badge variant="outline" className="rounded-full border-slate-700 text-[10px] text-slate-300">{proposal.status}</Badge></div><p className="mt-1 text-[10px] text-slate-500">Actor: authenticated user · Decision: {proposal.status === "Applied" ? "approval intent recorded" : "proposal rejected"} · Updated {new Date(proposal.updatedAt).toLocaleString()}</p><p className="mt-1 truncate text-[10px] text-slate-400">Context: {proposal.analysis?.slice(0, 140) || "Engineering proposal review decision"}</p></div>)}</div>}</div>
          <div className="hidden mt-3 rounded-xl border border-slate-800 bg-slate-900 p-3 text-[10px] leading-4 text-slate-400">
            <p className="font-semibold text-slate-200">How this workspace works</p>
            <p className="mt-1">Your protected session keeps project data user-scoped and chat context in this screen while you remain signed in. Background work is session- and runner-bound; it is not guaranteed to continue after the active session ends. Pending proposals stay queued with Proposed status for your next approval or an authorized runner. The agent can analyze and propose code, but it does not claim that files, commands, tests, or deployments happened unless an authorized runner reports them.</p>
          </div>
              <div className="mt-4 rounded-xl border border-slate-800 bg-slate-900 p-3 text-xs text-slate-300"><p className="font-semibold text-cyan-200">Universal self-run generation</p><p className="mt-1 leading-5">Prompt kisi bhi language mein likhein; target platform aur runtime/framework select karein. Runner ki zaroorat nahi: aapko complete files, direct commands, verification aur rollback package milega.</p><div className="mt-3 grid gap-2 sm:grid-cols-2"><select value={targetId} onChange={(e) => setTargetId(e.target.value as UniversalTargetId)} className="h-9 rounded-md border border-slate-700 bg-slate-950 px-2 text-[11px] text-slate-300">{universalTargets.map((target) => <option key={target.id} value={target.id}>{target.label}</option>)}</select><Input value={projectType} onChange={(e) => setProjectType(e.target.value)} placeholder="Website, API, automation, security baseline..." className="h-9 border-slate-700 bg-slate-950 text-[11px] text-slate-200 placeholder:text-slate-600" /><Input value={runtime} onChange={(e) => setRuntime(e.target.value)} placeholder="Runtime/framework: PowerShell, Python, Node.js, FastAPI..." className="h-9 border-slate-700 bg-slate-950 text-[11px] text-slate-200 placeholder:text-slate-600" /><select value={permissionLevel} onChange={(e) => setPermissionLevel(e.target.value as PermissionLevel)} className="h-9 rounded-md border border-slate-700 bg-slate-950 px-2 text-[11px] text-slate-300"><option value="standard">Standard user</option><option value="administrator">Administrator approved</option><option value="owner-confirmed">Owner-authorized target</option></select><select value={generationMode} onChange={(e) => setGenerationMode(e.target.value as typeof generationMode)} className="h-9 rounded-md border border-slate-700 bg-slate-950 px-2 text-[11px] text-slate-300"><option value="free">Free starter and preflight package</option><option value="local">Free local Ollama code-generation package</option><option value="model">Optional configured-model proposal</option></select></div><label className="mt-3 flex items-start gap-2 text-[11px] leading-4 text-slate-400"><input type="checkbox" checked={targetConfirmed} onChange={(e) => setTargetConfirmed(e.target.checked)} className="mt-0.5 accent-cyan-400" />I confirm this is my authorized target and I will review preflight output before any change command.</label><p className="mt-2 text-[11px] text-slate-500">{generationMode === "free" ? "Free starter: no provider is required for target contract, preflight and verification package." : generationMode === "local" ? "Local model: SynapseX creates a self-run Ollama package. Model download and generation happen on your own computer, with no paid API required." : "Model-enhanced: returns complete custom source proposals through an optional configured model; execution remains self-run."}</p><div className="mt-3 grid gap-2 sm:grid-cols-2"><Button type="button" variant="outline" onClick={() => { setExecutionMode("self"); }} className={cn("border-slate-700 text-xs", executionMode === "self" && "border-cyan-300 bg-cyan-400/10 text-cyan-200")}>I will run commands</Button><Button type="button" variant="outline" onClick={() => { setExecutionMode("runner"); }} className={cn("border-slate-700 text-xs", executionMode === "runner" && "border-cyan-300 bg-cyan-400/10 text-cyan-200")}>Optional remote runner</Button></div><p className="mt-2 text-[11px] text-slate-500">{executionMode === "self" ? "Self-run default: complete files, save steps aur copyable platform-specific commands milengi." : "Runner optional hai aur kabhi mandatory nahi; approved build connected runner ko bheji jayegi."}</p>{buildPrompt.trim() && <div className="mt-3 rounded-lg border border-amber-300/20 bg-amber-300/5 p-2"><p className="text-[10px] font-semibold uppercase tracking-[0.14em] text-amber-200">{protectionRecommendation.title}</p><p className="mt-1 text-[11px] leading-4 text-slate-400">{protectionRecommendation.body}</p></div>}<label className="mt-3 flex items-start gap-2 text-[11px] leading-4 text-slate-400"><input type="checkbox" checked={pathUnknown} onChange={(e) => { setPathUnknown(e.target.checked); if (!e.target.checked) setPathConfirmed(false); }} className="mt-0.5 accent-cyan-400" />Mujhe folder ka exact path nahi pata; pehle safe read-only discovery aur path confirmation chahiye.</label>{pathUnknown && <div className="mt-3 space-y-2"><select value={discoveryOs} onChange={(e) => setDiscoveryOs(e.target.value as DiscoveryOs)} className="h-9 w-full rounded-md border border-slate-700 bg-slate-950 px-2 text-[11px] text-slate-300"><option>Windows</option><option>Unix</option></select><pre className="whitespace-pre-wrap rounded-lg bg-slate-950 p-2 font-mono text-[10px] leading-4 text-slate-400">{getDiscoveryCommand(discoveryOs, inferredFolderName || "Final Leads")}</pre>{executionMode === "runner" && <Button type="button" variant="outline" onClick={discoverFolderOnRunner} disabled={runScript.isPending || !projectId || !inferredFolderName} className="w-full border-cyan-300/30 text-[11px] text-cyan-200">{runScript.isPending ? "Searching on runner..." : `Auto-discover ${inferredFolderName || "folder"} on my laptop`}</Button>}<Textarea value={discoveryOutput} onChange={(e) => { const output = e.target.value; setDiscoveryOutput(output); const paths = parsePowerShellPaths(output); if (paths.length === 1) setDiscoveredPath(paths[0]); setPathConfirmed(false); }} placeholder="PowerShell ka poora output yahan paste karein" className="min-h-16 border-slate-700 bg-slate-950 text-[11px] text-slate-200 placeholder:text-slate-600" />{parsedPaths.length > 0 && <select value={discoveredPath} onChange={(e) => { setDiscoveredPath(e.target.value); setPathConfirmed(false); }} className="h-9 w-full rounded-md border border-slate-700 bg-slate-950 px-2 text-[11px] text-slate-300"><option value="">Parsed path select karein</option>{parsedPaths.map((path) => <option key={path} value={path}>{path}</option>)}</select>}{discoveredPath && <div className="rounded-lg border border-cyan-400/20 bg-cyan-400/5 p-2"><p className="text-[10px] font-semibold uppercase tracking-[0.14em] text-cyan-200">Read-only ACL preview</p><p className="mt-1 text-[10px] text-slate-400">Protection se pehle current owner/access dekhne ke liye yeh command run karein:</p><pre className="mt-2 whitespace-pre-wrap font-mono text-[10px] leading-4 text-slate-300">{getAclPreviewCommand(discoveredPath)}</pre><Textarea value={aclOutput} onChange={(e) => setAclOutput(e.target.value)} placeholder="Get-Acl ka output yahan paste karein (optional)" className="mt-2 min-h-14 border-slate-700 bg-slate-950 text-[10px] text-slate-200 placeholder:text-slate-600" />{aclOutput.trim() && <div className="mt-2 space-y-2 text-[10px]"><div className="grid gap-2 sm:grid-cols-2"><div className="rounded border border-slate-700 bg-slate-950 p-2"><p className="font-semibold text-slate-300">Current ACL captured</p><p className="mt-1 text-slate-500">{parsedAclAccounts.length ? `${parsedAclAccounts.length} account entries parsed.` : "Output saved; account lines parse nahi ho sakin."}</p>{parsedAclAccounts.length > 0 && <div className="mt-2 space-y-1">{parsedAclAccounts.map((entry, index) => <div key={`${entry.account}-${index}`} className="flex justify-between gap-2 border-t border-slate-800 pt-1"><span className="truncate text-slate-300">{entry.account}</span><span className={entry.effect === "deny" ? "text-rose-300" : "text-slate-500"}>{entry.access}</span></div>)}</div>}</div><div className="rounded border border-emerald-400/20 bg-emerald-400/5 p-2"><p className="font-semibold text-emerald-200">Proposed protection</p><p className="mt-1 text-slate-400">Owner/admin access preserve; extra users ke write/modify rights ko change karne se pehle explicit review zaroori hai.</p><p className="mt-2 font-semibold text-amber-200">Rollback preview</p><p className="mt-1 break-all font-mono text-[9px] text-slate-500">{getRollbackPreviewCommand(discoveredPath)}</p></div></div></div>}</div>}<label className="flex items-start gap-2 text-[11px] leading-4 text-slate-400"><input type="checkbox" checked={pathConfirmed} disabled={!discoveredPath.trim()} onChange={(e) => setPathConfirmed(e.target.checked)} className="mt-0.5 accent-cyan-400" />I confirm this discovered path is the intended folder.</label></div>}</div><div className="mt-4 grid gap-3 md:grid-cols-[1fr_220px]">
            <Textarea value={buildPrompt} onChange={(e) => setBuildPrompt(e.target.value)} placeholder="Misal: Mere liye ek secure private-company portal banao, login, role-based access aur admin dashboard ke saath. Ya: Python mein invoice automation tool banao." className="min-h-28 resize-y border-slate-800 bg-slate-900 text-sm text-slate-100 placeholder:text-slate-600" />
            <div className="space-y-3">
              <select value={projectId ?? ""} onChange={(e) => setProjectId(Number(e.target.value) || undefined)} className="h-10 w-full rounded-md border border-slate-800 bg-slate-900 px-3 text-sm text-slate-300"><option value="">No project context</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select>
              <div className="flex gap-2"><Button type="button" variant="outline" onClick={resetBuilder} className="border-slate-700 text-slate-300">Reset</Button><Button disabled={build.isPending || buildPrompt.trim().length < 8 || (pathUnknown && !pathConfirmed)} onClick={() => { setLastBuildPrompt(buildPrompt.trim()); build.mutate({ prompt: proposalPrompt, projectId, generationMode, context: generationContext }); }} className="flex-1 bg-cyan-400 text-slate-950 hover:bg-cyan-300">{build.isPending ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Code2 className="mr-2 size-4" />} Create self-run package</Button></div>
            </div>
          </div>
          {buildError && <div className="mt-3 rounded-xl border border-red-400/30 bg-red-950/40 p-3 text-xs leading-5 text-red-200"><p className="font-semibold">Builder error</p><p className="mt-1">{buildError}</p><p className="mt-1 text-red-300/80">Prompt ko chhote implementation steps mein split karke dobara try karein, ya Assistant mein error detail share karein.</p></div>}
          {latest && <div className="mt-4 space-y-4 rounded-2xl border border-slate-800 bg-slate-900/80 p-4">
            <Badge variant="outline" className="rounded-full border-cyan-400/30 text-cyan-300">{latest.status === "Proposed" ? "Build ready" : latest.status}</Badge>
            <div><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Analysis</p><p className="mt-1 text-xs leading-5 text-slate-300">{"analysis" in latest ? latest.analysis : ""}</p></div>
            <div><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Project operations</p><ul className="mt-2 space-y-1 text-xs text-slate-300">{(Array.isArray(latest.operations) ? latest.operations : parse(latest.operations as string)).map((operation: string, index: number) => <li key={index}>• {operation}</li>)}</ul></div>
            <div><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">File actions</p><div className="mt-2 space-y-1">{(Array.isArray(latest.fileActions) ? latest.fileActions : parse(latest.fileActions as string)).map((item: { action?: string; path?: string; reason?: string }, index: number) => <p key={index} className="text-xs text-slate-300"><span className="mr-2 rounded border border-slate-700 px-1.5 py-0.5 font-mono text-[10px] text-cyan-300">{item.action}</span>{item.path} <span className="text-slate-500">— {item.reason}</span></p>)}</div></div>
            {Array.isArray(latest.files) && latest.files.length > 0 && <div><div className="flex items-center justify-between gap-2"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Complete file contents</p><p className="text-[10px] text-amber-300/80">These files are not on your laptop until you save them.</p></div><div className="mt-2 space-y-2">{latest.files.map((file: { path?: string; purpose?: string; content?: string }, index: number) => <div key={index} className="rounded-lg border border-slate-800 bg-slate-950 p-2"><div className="flex items-start justify-between gap-2"><div><p className="font-mono text-[11px] text-cyan-200">{file.path}</p><p className="mt-1 text-[10px] text-slate-500">{file.purpose}</p></div><div className="flex shrink-0 gap-2"><Button type="button" size="sm" variant="outline" onClick={() => copyFileContent(file.content ?? "")} className="border-slate-700 text-[10px] text-slate-300">Copy file</Button><Button type="button" size="sm" variant="outline" onClick={() => downloadFileContent(file.path ?? "generated-file.txt", file.content ?? "")} className="border-slate-700 text-[10px] text-slate-300">Download</Button></div></div><pre className="mt-2 max-h-56 overflow-auto whitespace-pre-wrap rounded bg-black/40 p-2 font-mono text-[10px] leading-4 text-slate-300">{file.content}</pre></div>)}</div></div>}
            <div><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Verification plan</p><ul className="mt-2 space-y-1 text-xs text-slate-300">{(Array.isArray(latest.verification) ? latest.verification : parse(latest.verification as string)).map((step: string, index: number) => <li key={index}>• {step}</li>)}</ul></div>
            <div><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">Proposed diffs</p><div className="mt-2 space-y-2">{(Array.isArray(latest.diffs) ? latest.diffs : parse(latest.diffs as string)).slice(0, 6).map((item: { path?: string; diff?: string }, index: number) => <div key={index} className="rounded-lg bg-slate-950 p-2"><p className="font-mono text-[11px] text-cyan-200">{item.path}</p><pre className="mt-1 max-h-28 overflow-auto whitespace-pre-wrap font-mono text-[10px] leading-4 text-slate-400">{item.diff}</pre></div>)}</div></div>
            {executionMode === "self" && <div className="rounded-lg border border-amber-400/20 bg-amber-400/5 p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-amber-200">Self-run safety checklist</p><ul className="mt-2 space-y-1 text-[11px] leading-4 text-slate-300"><li>1. Confirm the discovered folder path before any protection command.</li><li>2. Run the supplied command in PowerShell/Shell and save the exact output.</li><li>3. Verify access behavior and preserve the rollback command before continuing.</li><li>4. Paste any failure into execution feedback; this workspace never claims execution automatically.</li></ul></div>}
            {pathUnknown && executionMode === "self" && (
              <div className="rounded-lg border border-cyan-400/20 bg-cyan-400/5 p-3">
                <p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-cyan-200">Read-only path discovery starter</p>
                <p className="mt-1 text-[10px] leading-4 text-slate-400">Windows PowerShell mein pehle yeh command paste karein. Result mein exact path aaye to Builder mein path confirm karein; protection command us se pehle run na karein.</p>
                <pre className="mt-2 whitespace-pre-wrap rounded-lg bg-slate-950 p-2 font-mono text-[10px] leading-4 text-slate-300">Get-ChildItem -Path $HOME -Directory -Filter 'Final Leads' -Recurse -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName</pre>
              </div>
            )}
            <div>
              <div className="flex items-center justify-between gap-2">
                <p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-500">PowerShell / Shell commands</p>
                {executionMode === "self" && <Button type="button" size="sm" variant="outline" onClick={() => copyCommands(Array.isArray(latest.commands) ? latest.commands : parse(latest.commands as string))} className="border-slate-700 text-[10px] text-slate-300">Copy commands</Button>}
              </div>
              <pre className="mt-2 max-h-32 overflow-auto whitespace-pre-wrap rounded-lg bg-slate-950 p-3 font-mono text-[10px] leading-5 text-slate-300">{(Array.isArray(latest.commands) ? latest.commands : parse(latest.commands as string)).join("\n")}</pre>
            </div>
            <Textarea value={executionFeedback} onChange={(e) => setExecutionFeedback(e.target.value)} placeholder="Command run karne par error aaye to exact error yahan paste karein..." className="mt-3 min-h-20 border-slate-800 bg-slate-950 text-xs text-slate-200 placeholder:text-slate-600" />
            <Button size="sm" variant="outline" disabled={!executionFeedback.trim()} onClick={submitExecutionFeedback} className="mt-2 border-slate-700 text-slate-300">Send execution feedback to Assistant</Button>
              <div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={continueBuildStage} disabled={build.isPending || !lastBuildPrompt.trim()} className="border-cyan-400/30 text-cyan-200">Continue next stage</Button><Button size="sm" variant="outline" onClick={() => downloadProposal(latest)} className="border-slate-700 text-slate-300">Export files</Button>{executionMode === "runner" && <Button size="sm" onClick={sendToAutoRunner} disabled={createProject.isPending || createScript.isPending || runScript.isPending} className="bg-emerald-600 hover:bg-emerald-700">{createProject.isPending || createScript.isPending || runScript.isPending ? "Preparing build..." : runnerConfirm ? "Confirm & execute on runner" : "Approve & execute"}</Button>}{executionMode === "self" && <Button size="sm" variant="outline" onClick={() => setRunnerStatus("Self-run selected: files copy karein, save karein, phir commands manually run karein.")} className="border-slate-700 text-slate-300">Show self-run steps</Button>}</div>
              {runnerStatus && <p className="rounded-lg border border-cyan-400/20 bg-cyan-400/5 p-2 text-[11px] leading-4 text-cyan-100">{runnerStatus}</p>}
            <p className="text-[10px] leading-4 text-amber-300/80">Approve karne ke baad package authorized runner ko bheja jata hai; files likhne aur commands chalne ka result runner callback ke baghair verified nahi maana jata.</p>
          </div>}
        </div>
      </section>
    </div>
  );
}

function EmptyState({ icon: Icon, title, body }: { icon: React.ElementType; title: string; body: string }) { return <div className="flex min-h-56 flex-col items-center justify-center rounded-2xl border border-dashed border-slate-200 bg-white/60 p-8 text-center"><span className="mb-4 flex size-12 items-center justify-center rounded-2xl bg-slate-100 text-slate-400"><Icon className="size-5" /></span><h3 className="font-semibold text-slate-800">{title}</h3><p className="mt-2 max-w-md text-sm leading-6 text-slate-500">{body}</p></div>; }
function LoadingCard() { return <div className="flex min-h-44 items-center justify-center rounded-2xl bg-white"><Loader2 className="size-5 animate-spin text-primary" /></div>; }

export default function Home() { const [location] = useLocation(); const section = location === "/" ? "/assistant" : navLabels[location] ? location : "/assistant"; const View = section === "/projects" ? Projects : section === "/tasks" ? Tasks : section === "/changes" ? Changes : section === "/audits" ? Audits : section === "/automation" ? Automation : section === "/testing" ? Testing : section === "/reports" ? Reports : Assistant; const commandCenter = section === "/assistant"; return <DashboardLayout fullHeight={commandCenter} commandCenter={commandCenter}><div className={cn(commandCenter ? "min-h-screen w-full min-w-0 max-w-full overflow-x-hidden bg-[#101416] px-3 py-3 text-slate-100 sm:px-4 sm:py-4" : "min-h-screen bg-[#f7f8fb] px-4 py-6 text-slate-950 md:px-8 md:py-8")}><div className={cn("mx-auto max-w-[1480px]", commandCenter && "min-h-screen w-full min-w-0 max-w-full")}><div className={commandCenter ? "hidden" : "mb-8 flex items-center justify-between"}><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-2xl bg-slate-950 text-cyan-300 shadow-lg shadow-slate-950/10"><CircleDashed className="size-5" /></div><div><p className="text-sm font-semibold tracking-tight text-slate-950">SynapseX PowerShell Engineering Studio</p><p className="text-xs text-slate-400">{navLabels[section]}</p></div></div><div className="hidden items-center gap-2 rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs text-slate-500 md:flex"><span className="size-1.5 rounded-full bg-emerald-500" /> Workspace protected</div></div>{commandCenter ? <AssistantRecoveryBoundary><SimplePromptStudio /></AssistantRecoveryBoundary> : <View />}</div></div></DashboardLayout>; }
